const base = '/Users/tamastyukodi/Development/video-platform-ui';
const http = require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/http-client.ts').default;
const MockAdapter = require('/Users/tamastyukodi/Development/video-platform-ui/node_modules/axios-mock-adapter').default;
const mock = new MockAdapter(http, {delayResponse: 80});
mock.onGet('api/user/userInfo').reply(200, {id:'qa-local-creator',firstName:'QA',lastName:'Fixture',email:'qa@example.test',roles:['CREATOR'],onboardingCompleted:true});
const qaFault = new URLSearchParams(window.location.search).get('qaFault') || '';
const faultPatterns = {
 'dashboard': /^api\/creator\/dashboard\/summary/,
 'sales-summary': /^api\/creator\/sales\/summary/,
 'sales-ledger': /^api\/creator\/orders(?:\?|$)/,
 'analytics': /^api\/creator\/analytics\/overview/,
 'customers': /^api\/creator\/customers(?:\?|$)/,
};
if (faultPatterns[qaFault]) {
 mock.onGet(faultPatterns[qaFault]).reply(request => {
  console.info('[QA controlled failure]',qaFault,request.method,request.url,'503 after 15000ms');
  return new Promise(resolve => setTimeout(() => resolve([503,{message:'Synthetic isolated QA service failure'}]),15000));
 });
}
require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/test-fixtures/creator-dashboard-http.mock.ts').registerCreatorDashboardTestMocks(mock);
require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/test-fixtures/creator-customers-http.mock.ts').registerCreatorCustomersTestMocks(mock);
require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/test-fixtures/creator-sales-http.mock.ts').registerCreatorSalesTestMocks(mock);
require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/test-fixtures/creator-analytics-http.mock.ts').registerCreatorAnalyticsTestMocks(mock);
mock.onGet(/api\/products\?(?:ownerId|userId)=/).reply(200,[]);
